export type PdfPageKind = 'text' | 'image' | 'mixed' | 'vector' | 'blank' | 'unknown';
export interface PdfPageInspection {
  page: number; kind: PdfPageKind; route: 'native' | 'ocr' | 'skip' | 'review';
  reasons: ('usable_native_text' | 'no_native_text' | 'suspect_text_encoding' | 'undecodable_text' | 'large_image_with_sparse_text' | 'outlined_text_with_sparse_native_text' | 'invisible_text_layer' | 'vector_content' | 'no_painted_content' | 'uncertain_graphics' | 'extraction_failed')[];
  native_characters: number; suspicious_characters: number; text_operations: number;
  invisible_text_operations: number; image_count: number; image_coverage: number | null;
  painted_paths: number;
  ocr_status: 'not_needed' | 'not_requested' | 'applied' | 'empty' | 'failed' | 'budget_exhausted';
}
export interface PdfInspection {
  schema_version: string; kind: PdfPageKind; page_count: number;
  pages: PdfPageInspection[]; pages_needing_ocr: number[];
}
export type Format = 'text' | 'markdown' | 'csv' | 'tsv' | 'notebook' | 'docx' | 'pdf' | 'xlsx' | 'xls' | 'xlsb' | 'pptx' | 'ppt' | 'odt' | 'ods' | 'odp' | 'epub' | 'rtf' | 'doc';
export interface OcrSource { image_size: [number, number]; quad: [[number, number], [number, number], [number, number], [number, number]]; confidence: number }
export interface PdfRegionSource { image_size: [number, number]; bbox: [number, number, number, number]; order: number; label: string; confidence?: number }
export interface Source { pdf_region?: PdfRegionSource; ocr?: OcrSource; page?: number; part?: string; cell?: number; row?: number; byte_range?: [number, number] }
export interface Diagnostic { code: string; message: string; source: Source; content_loss: boolean; category: 'missing_content' | 'formatting_limitation' | 'informational'; evidence: 'detected' | 'unverified' }
export interface Limits {
  max_image_bytes?: number; max_images?: number;
  max_input_bytes?: number; max_text_bytes?: number; max_nodes?: number;
  max_depth?: number; max_table_cells?: number; max_pages?: number;
  /** Additional cells generated by row/column repetition. */
  max_cell_repetitions?: number;
  max_archive_entries?: number; max_expanded_bytes?: number;
  /** Native Markdown writer only; includes markup and empty cells. */
  max_markdown_bytes?: number;
}
export interface Options { extract_images?: boolean; export_images?: boolean; filename?: string; format?: Format; strict?: boolean; partial_on_limit?: boolean; pdf_normalize_unicode?: boolean; csv_has_headers?: boolean; csv_delimiter?: string; csv_encoding?: 'utf8' | 'utf16_le' | 'utf16_be' | 'windows1252'; limits?: Limits }
export type Inline = {type: 'text' | 'code'; text: string}
  | {type: 'math'; tex: string; display: boolean} | {type: 'anchor'; id: string}
  | {type: 'strong' | 'emphasis' | 'strike'; children: Inline[]}
  | {type: 'link'; url: string; children: Inline[]}
  | {type: 'image'; url: string; alt: string} | {type: 'break'};
export interface Cell { blocks: Block[]; col_span: number; row_span: number; source: Source }
export type Block = {id: string; source: Source} & (
  {type: 'paragraph'; inlines: Inline[]} | {type: 'heading'; level: number; inlines: Inline[]}
  | {type: 'code'; language: string; text: string} | {type: 'quote'; blocks: Block[]}
  | {type: 'list'; start: number | null; items: Block[][]}
  | {type: 'table'; rows: Cell[][]; header_rows: number}
  | {type: 'thematic_break'} | {type: 'raw'; media_type: string; text: string});
export interface ImageAsset { id: string; media_type: string; source: Source; /** Base64-encoded original image bytes. */ data: string }
export interface Conversion {
  pdf_inspection?: PdfInspection;
  document: {schema_version: string; format: Format; blocks: Block[]; assets: ImageAsset[]};
  status: 'complete' | 'partial'; diagnostics: Diagnostic[];
  coverage: {source: Source; status: 'complete' | 'partial'}[];
  parser_version: string; markdown: string; render_diagnostics: Diagnostic[];
}
export function parse(bytes: Uint8Array, options?: Options): Promise<Conversion>;
export function parseFile(path: string, options?: Options): Promise<Conversion>;
export interface MarkdownSummary {
  image_count: number; images: { id: string; media_type: string; source: Source; path: string; bytes: number }[];
  format: Format; status: 'complete' | 'partial'; diagnostics: Diagnostic[];
  render_diagnostics: Diagnostic[]; coverage: Conversion['coverage'];
  pdf_inspection: PdfInspection | null; parser_version: string; bytes_written: number;
}
/** Write Markdown atomically without a JS document/Markdown buffer; never overwrite an existing destination. */
export function parseFileToMarkdown(input: string, output: string, options?: Omit<Options, 'filename'>): Promise<MarkdownSummary>;
export function capabilities(): {format: Format; enabled: boolean; level: string; notes: string}[];

export function inspectPdf(bytes: Uint8Array, options?: Options): Promise<PdfInspection>;
